/// <summary>
/// find last created record by item rec id
/// </summary>
/// <param name = "_recId">Rec Id of NDXHK1History record</param>
/// <param name = "_forupdate">for update</param>
/// <returns>NDXHK1MGKHistory record</returns>
public static NDXHK1History find(RecId _recId, boolean _forupdate = false)
{
    NDXHK1History lNDXHK1History;

    lNDXHK1History.selectForUpdate(_forupdate);

    select firstonly lNDXHK1History order by lNDXHK1History.CreatedDateTime desc
        where lNDXHK1History.RecId == _recId;

    return lNDXHK1History;
}

/// <summary>
/// find last created record by item rec id
/// </summary>
/// <param name = "_inventTableRefRecId">Rec Id of invent table record</param>
/// <param name = "_lastDateTime">upper limit last date</param>
/// <param name = "_forupdate">for update</param>
/// <returns>NDXHK1MGKHistory record</returns>
public static NDXHK1History findLast(RefRecId _inventTableRefRecId, utcdatetime _lastDateTime = DateTimeUtil::minValue(),  boolean _forupdate = false)
{
    NDXHK1History lNDXHK1History;

    lNDXHK1History.selectForUpdate(_forupdate);

    if(_lastDateTime > DateTimeUtil::minValue())
    {
        select firstonly lNDXHK1History order by lNDXHK1History.CreatedDateTime desc
            where lNDXHK1History.InventTableRefRecId == _inventTableRefRecId
                && lNDXHK1History.CreatedDateTime <= _lastDateTime;
    }
    else
    {
        select firstonly lNDXHK1History order by lNDXHK1History.CreatedDateTime desc
            where lNDXHK1History.InventTableRefRecId == _inventTableRefRecId;
    }

    return lNDXHK1History;
}

/// <summary>
/// Create History by InventTableModule
/// </summary>
/// <param name = "_inventTableModule">InventTableModule table record</param>
/// <param name = "_orig">InventTableModule table record before change</param>
public static void createByInventTableModule(InventTableModule _inventTableModule, InventTableModule _orig = null)
{
    InventTable lInventTable = InventTable::find(_inventTableModule.ItemId);
    NDXHK1History lNDXHK1History = NDXHK1History::findLast(lInventTable.RecId, DateTimeUtil::minValue());

    NDXHK1History newHistoryRecord;

    newHistoryRecord.InventTableRefRecId = lInventTable.RecId;

    if(lNDXHK1History.HK1To != _inventTableModule.Price)
    {
        newHistoryRecord.HK1From = lNDXHK1History.HK1To;
        newHistoryRecord.HK1To = _inventTableModule.Price;

        if(_orig)
        {
            newHistoryRecord.HK1From = _orig.Price;
        }

        newHistoryRecord.insert();
    }
}

/// <summary>
/// Displays total HK2 Price by history value "To"
/// </summary>
/// <returns> HK2 Price</returns>
[SysClientCacheDataMethodAttribute(true)]
display NDXHK2To dispHK2PriceTo()
{
    Price hk2Price = 0;
    Price hk1 = this.HK1To;

    if(!xUserInfo::hasSecuritykeyAccess(privilegeStr(NDXHK2View)))
    {
        return 0;
    }

    if(!xUserInfo::hasSecuritykeyAccess(privilegeStr(NDXHK1View)))
    {
        hk1 = 0;
    }

    hk2Price= hk1 * NDXHK2GroupHistory::getHK2HistoryFactor(this.InventTableRefRecId, this.CreatedDateTime)
            * NDXMGKGroupHistory::getMGKHistoryFactor(this.InventTableRefRecId, this.CreatedDateTime);

    return hk2Price;
}

